def write_complete(path: Path, text: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text.lstrip(), encoding="utf-8", newline="\n")
    ast.parse(path.read_text(encoding="utf-8"), filename=str(path))
    print(f"[OK] FULL REPLACEMENT: {path.resolve()}")


def main() -> int:
    print("=" * 48)
    print(" OML-070 INSTALLER")
    print(" CERTIFIED MARKET-BEHAVIOR RELATIONSHIP GRAPH")
    print("=" * 48)
    print("[BOOT] Revision: CURRENT_REPOSITORY_OML_069_031_TWO_ENTITY_ALIGNMENT")
    try:
        missing = [str(ROOT / item) for item in UPSTREAM_FILES if not (ROOT / item).is_file()]
        if missing:
            raise RuntimeError("Required certified files missing: " + ", ".join(missing))

        tracked = {ROOT / item: (ROOT / item).read_bytes() for item in UPSTREAM_FILES}
        write_complete(PRODUCTION, PRODUCTION_SOURCE)
        write_complete(TEST, TEST_SOURCE)

        export = "from .oracle_memory_certified_market_behavior_relationship_graph_070 import *"
        current = INIT.read_text(encoding="utf-8") if INIT.exists() else ""
        if export not in current.splitlines():
            if current and not current.endswith("\n"):
                current += "\n"
            current += export + "\n"
            INIT.write_text(current, encoding="utf-8", newline="\n")
            print(f"[OK] PACKAGE UPDATED: {INIT.resolve()}")
        else:
            print(f"[OK] PACKAGE EXPORT PRESENT: {INIT.resolve()}")

        completed = subprocess.run([sys.executable, str(TEST)], cwd=ROOT, check=False)
        if completed.returncode:
            raise RuntimeError(f"OML-070 test failed with exit code {completed.returncode}")

        for path, before in tracked.items():
            if path.read_bytes() != before:
                raise RuntimeError(f"Certified upstream changed: {path}")

        print("[PASS] Production fully replaced")
        print("[PASS] Standalone deterministic test installed")
        print("[PASS] Certified upstream remained unchanged")
        print("[PASS] Deterministic replay and immutable lineage preserved")
        print("[PASS] Persistence remained disabled")
        print("[PASS] Learning updates remained disabled")
        print("[PASS] Runtime activation remained disabled")
        print("[PASS] Publication remained disabled")
        print("[PASS] Action authorization remained disabled")
        print("[PASS] Q Series execution remained disabled")
        print("[DONE] OML-070 INSTALLED")
        return 0
    except (RuntimeError, SyntaxError, ImportError, AttributeError, KeyError, TypeError, ValueError) as exc:
        print(f"[ERROR] {exc}")
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
